/// Arc 146 slice 2 — substrate-primitive impl dispatch from
/// `eval_dispatch_call` when an arm's impl is NOT a user-define
/// `Function` (i.e., not present in `sym.functions`). Routes to the
/// per-Type Rust handler, passing the already-evaluated values so
/// side effects fire exactly once (sym.get path also fires once
/// via apply_function with pre-evaluated values).
///
/// Returns `Some(result)` when the impl is a known substrate
/// primitive; `None` when no substrate impl matches (caller surfaces
/// `UnknownFunction`).
///
/// Arc 146 slice 3 extends this with the per-Type empty? / contains? /
/// get / conj impls (10 new arms; 3+3+2+2).
///
/// Arc 146 slice 4 extends this with the per-Type assoc / dissoc /
/// keys / values / concat impls (5 new arms). These ops aren't
/// dispatched (alias-expansion goes through user-define), but the
/// substrate-impl entries here let the alias body resolve when the
/// per-Type impl is the named target.
pub(crate) fn dispatch_substrate_impl(
    impl_name: &str,
    vals: &[Value],
) -> Option<Result<Value, EvalBreak>> {
    use crate::collection::eval as ceval;
    match impl_name {
        ":wat::core::Vector/length" => {
            Some(ceval::vector_length_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::HashMap/length" => {
            Some(ceval::hashmap_length_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::HashSet/length" => {
            Some(ceval::hashset_length_inner(vals.first().expect("arity-checked")))
        }
        // Arc 220 Stone 220.4 — List/length
        ":wat::core::List/length" => {
            Some(ceval::list_length_inner(vals.first().expect("arity-checked")))
        }
        // empty? — 1 arg
        ":wat::core::Vector/empty?" => {
            Some(ceval::vector_empty_q_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::HashMap/empty?" => {
            Some(ceval::hashmap_empty_q_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::HashSet/empty?" => {
            Some(ceval::hashset_empty_q_inner(vals.first().expect("arity-checked")))
        }
        // Arc 220 Stone 220.4 — List/empty?
        ":wat::core::List/empty?" => {
            Some(ceval::list_empty_q_inner(vals.first().expect("arity-checked")))
        }
        // contains? — 2 args (mixed verbs)
        ":wat::core::Vector/contains?" => Some(ceval::vector_contains_q_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        ":wat::core::HashMap/contains-key?" => Some(ceval::hashmap_contains_key_q_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        ":wat::core::HashSet/contains?" => Some(ceval::hashset_contains_q_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // Arc 220 Stone 220.4 — List/contains?
        ":wat::core::List/contains?" => Some(ceval::list_contains_q_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // get — 2 args (return type varies per arm: Option<T> vs Option<V>)
        ":wat::core::Vector/get" => Some(ceval::vector_get_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        ":wat::core::HashMap/get" => Some(ceval::hashmap_get_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // Arc 220 Stone 220.4 — List/get
        ":wat::core::List/get" => Some(ceval::list_get_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // conj — 2 args (returns container type)
        ":wat::core::Vector/conj" => Some(ceval::vector_conj_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        ":wat::core::HashSet/conj" => Some(ceval::hashset_conj_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // Arc 220 Stone 220.4 — List/conj (PREPEND semantic)
        ":wat::core::List/conj" => Some(ceval::list_conj_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // Arc 146 slice 4 — assoc / dissoc / keys / values / concat
        // per-Type impls. Routed here so alias-expanded user-defines
        // resolve to the substrate impl when the body's call lands on
        // a per-Type primitive name.
        ":wat::core::HashMap/assoc" => Some(ceval::hashmap_assoc_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
            vals.get(2).expect("arity-checked"),
        )),
        ":wat::core::HashMap/dissoc" => Some(ceval::hashmap_dissoc_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        ":wat::core::HashMap/keys" => {
            Some(ceval::hashmap_keys_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::HashMap/values" => {
            Some(ceval::hashmap_values_inner(vals.first().expect("arity-checked")))
        }
        ":wat::core::Vector/concat" => Some(ceval::vector_concat_inner(
            vals.first().expect("arity-checked"),
            vals.get(1).expect("arity-checked"),
        )),
        // Arc 148 slice 4 — per-Type arithmetic leaves reachable via
        // direct substrate addressing (no-privacy doctrine). The binary
        // Dispatch entity decls were DELETED in arc 237 Stone 237.8a
        // (no more cross-type arms); these per-Type leaves remain as
        // the irreducible primitives.
        //
        // arc 237 Stone 237.8a — 4 same-type i64-i64 + 4 same-type
        // f64-f64 = 8 leaves. Mixed-type leaves (+'i64'f64 etc.)
        // DELETED under THE DECISION (`feedback_no_implicit_coercion`).
        // Stone 237.8b — drop '2 suffix from per-Type binary primitives.
        ":wat::core::i64::+" => Some(arith_i64_i64_inner(impl_name, vals, |a, b| Ok(a.wrapping_add(b)))),
        ":wat::core::i64::-" => Some(arith_i64_i64_inner(impl_name, vals, |a, b| Ok(a.wrapping_sub(b)))),
        ":wat::core::i64::*" => Some(arith_i64_i64_inner(impl_name, vals, |a, b| Ok(a.wrapping_mul(b)))),
        ":wat::core::i64::/" => Some(arith_i64_i64_inner(impl_name, vals, |a, b| {
            if b == 0 { Err(()) } else { Ok(a.wrapping_div(b)) }
        })),
        ":wat::core::f64::+" => Some(arith_f64_f64_inner(impl_name, vals, |a, b| Ok(a + b))),
        ":wat::core::f64::-" => Some(arith_f64_f64_inner(impl_name, vals, |a, b| Ok(a - b))),
        ":wat::core::f64::*" => Some(arith_f64_f64_inner(impl_name, vals, |a, b| Ok(a * b))),
        // Stone 237.8b — IEEE 754: f64 / 0.0 = ±Inf or NaN; not an error.
        ":wat::core::f64::/" => Some(arith_f64_f64_inner(impl_name, vals, |a, b| Ok(a / b))),
        _ => None,
    }
}

/// Arc 148 slice 4 — Value-level arithmetic leaves used by
/// `dispatch_substrate_impl` when a per-Type leaf is addressed directly.
/// Two same-type helpers remain (i64-i64, f64-f64).
///
/// arc 237 Stone 237.8a — mixed-type helpers (i64-f64, f64-i64)
/// DELETED under THE DECISION (`feedback_no_implicit_coercion`).
///
/// The `Err(())` channel signals divide-by-zero (the helper translates
/// to `RuntimeError::DivisionByZero` with a synthesized span — the
/// dispatch path doesn't have argument spans available, so the span
/// is unknown).
fn arith_i64_i64_inner<F>(
    impl_name: &str,
    vals: &[Value],
    op: F,
) -> Result<Value, EvalBreak>
where
    F: Fn(i64, i64) -> Result<i64, ()>,
{
    let a = vals.first().expect("arity-checked");
    let b = vals.get(1).expect("arity-checked");
    match (a, b) {
        (Value::i64(x), Value::i64(y)) => match op(*x, *y) {
            Ok(r) => Ok(Value::i64(r)),
            Err(()) => Err(RuntimeError { span: Span::unknown(), kind: RuntimeErrorKind::DivisionByZero }.into()),
        },
        _ => Err(RuntimeError { span: Span::unknown(), kind: RuntimeErrorKind::TypeMismatch {
            op: impl_name.into(),
            expected: "(i64, i64)",
            got: Box::new(ValueSnapshot::of(&a))
        } }.into()),
    }
}

fn arith_f64_f64_inner<F>(
    impl_name: &str,
    vals: &[Value],
    op: F,
) -> Result<Value, EvalBreak>
where
    F: Fn(f64, f64) -> Result<f64, ()>,
{
    let a = vals.first().expect("arity-checked");
    let b = vals.get(1).expect("arity-checked");
    match (a, b) {
        (Value::f64(x), Value::f64(y)) => match op(*x, *y) {
            Ok(r) => Ok(Value::f64(r)),
            Err(()) => Err(RuntimeError { span: Span::unknown(), kind: RuntimeErrorKind::DivisionByZero }.into()),
        },
        _ => Err(RuntimeError { span: Span::unknown(), kind: RuntimeErrorKind::TypeMismatch {
            op: impl_name.into(),
            expected: "(f64, f64)",
            got: Box::new(ValueSnapshot::of(&a))
        } }.into()),
    }
}

