fn require_holon(op: &str, v: Value) -> Result<Arc<HolonAST>, EvalBreak> {
    match v {
        Value::holon__HolonAST(h) => Ok(h),
        other => Err(RuntimeError { span: Span::unknown(), kind: RuntimeErrorKind::TypeMismatch {
            op: op.into(),
            expected: "Holon",
            got: Box::new(ValueSnapshot::of(&other)),
            // arc 138: no — takes Value, not WatAST; no source coords available
        } }.into()),
    }
}

/// Arc 234 Stone 234.5 — centralized "ensure HolonAST" helper (D1).
///
/// Accepts either a HolonAST value (existing case) OR a wat::Record value
/// (NEW — auto-unwraps the pre-built holon_form). Records flow through VSA
/// verbs natively without user-facing conversion calls; this helper is the
/// single site that normalises the two representations into a HolonAST.
///
/// Pattern mirrored from T1 trap-door: `holon_form.as_ref().clone()` is
/// safe even when the Arc is shared (proven at Stone 234.2a eval_record_field_at).
fn coerce_to_holon_ast(op: &str, v: Value, arg_span: &Span) -> Result<HolonAST, EvalBreak> {
    match v {
        Value::holon__HolonAST(h) => Ok((*h).clone()),
        Value::wat__holon__Record { holon_form, .. } => Ok(holon_form.as_ref().clone()),
        // Stone S-C.2c — Bucket C teaching error: base record has no holon flavor.
        Value::wat__Record { class_fqdn, .. } => Err(RuntimeError { span: arg_span.clone(), kind: RuntimeErrorKind::MalformedForm {
            head: op.into(),
            reason: format!(
                "base record `{}` has no holon flavor; construct a holonic record \
                 (`:wat::holon::Record::def`) to use holon operations",
                class_fqdn
            )
        } }.into()),
        other => Err(RuntimeError { span: arg_span.clone(), kind: RuntimeErrorKind::TypeMismatch {
            op: op.into(),
            expected: "HolonAST or wat::Record",
            got: Box::new(ValueSnapshot::of(&other))
        } }.into()),
    }
}

// ─── Arc 226 Stone 226.1 — Type predicates (classifier-name match) ───────────
//
// Type checking emerges from VSA similarity — per [[typed-entities-doctrine]]:
//   (is-X? value) ≡ similarity(value's class atom vector, prototype-of-X vector)
//
// Stone 226.1 ships v1: EXACT STRUCTURAL MATCH on classifier name.
// The classifier name IS a perfect VSA similarity probe in the degenerate
// (exact-match) case — two identical atom strings produce identical vectors,
// cosine = 1.0. Future stones 226.2+ add threshold-tunable continuous scoring.
//
// All functions share the same shape:
//   1. Evaluate the HolonAST argument.
//   2. Call `extract_classifier` (arc 228 helper) to recover the classifier name.
//   3. Compare against the expected class name (or check `is_nil()` for Nil).
//   4. Return `Value::bool(matches)`.
//
// Non-HolonAST values (bare i64, String, etc.) are accepted but return false —
// the absence of a classifier is an honest "not this type" signal.

/// `(:wat::holon::is? value class-name) -> :bool` — polymorphic type predicate.
///
/// Arc 226 Stone 226.1. Accepts any classifier-wrapped HolonAST as `value` and
/// a `String` as `class-name`. Calls `extract_classifier`; compares the result
/// against `class-name`. Returns `true` iff the outermost classifier matches.
///
/// For non-HolonAST values (bare i64, String, bool, etc.), returns `false` —
/// the absence of a classifier is "not of the named type."
///
/// Examples:
///   `(is? (:wat::holon::to-holon {:a 1}) "Map")` → true
///   `(is? (:wat::holon::to-holon #{1 2}) "Map")` → false
fn eval_holon_is_predicate(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::holon::is?";
    if args.len() != 2 {
        return Err(RuntimeError { span: list_span.clone(), kind: RuntimeErrorKind::ArityMismatch {
            op: OP.into(),
            expected: 2,
            got: args.len()
        } }.into());
    }
    let value_val = eval_inner(&args[0], env, sym)?.value_owned();
    let class_val = eval_inner(&args[1], env, sym)?.value_owned();
    let class_name = match class_val {
        Value::String(s) => s,
        other => {
            return Err(RuntimeError { span: args[1].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "String (classifier name)",
                got: Box::new(ValueSnapshot::of(&other))
            } }.into());
        }
    };
    let matches = match value_val {
        Value::holon__HolonAST(h) => extract_classifier(&h).as_deref() == Some(class_name.as_str()),
        _ => false,
    };
    Ok(Value::bool(matches))
}

