/// `(:wat::holon::Reckoner/new-discrete name dims recalib-interval labels) -> :Reckoner`
fn eval_reckoner_new_discrete(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    if args.len() != 4 {
        return Err(RuntimeError { span: list_span.clone(), kind: RuntimeErrorKind::ArityMismatch {
            op: ":wat::holon::Reckoner/new-discrete".into(),
            expected: 4,
            got: args.len()
        } }.into());
    }
    let name_val = eval_inner(&args[0], env, sym)?.value_owned();
    let name = match name_val {
        Value::String(s) => (*s).clone(),
        other => {
            return Err(RuntimeError { span: args[0].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: ":wat::holon::Reckoner/new-discrete".into(),
                expected: "String",
                got: Box::new(ValueSnapshot::of(&other))
            } }.into())
        }
    };
    let dims = require_i64(":wat::holon::Reckoner/new-discrete", eval_inner(&args[1], env, sym)?.value_owned())?;
    let recalib =
        require_i64(":wat::holon::Reckoner/new-discrete", eval_inner(&args[2], env, sym)?.value_owned())?;
    let labels_val = eval_inner(&args[3], env, sym)?.value_owned();
    let label_asts: Vec<HolonAST> = match labels_val {
        Value::Vec(items) => {
            let mut out = Vec::with_capacity(items.len());
            for item in items.iter() {
                let h = require_holon(
                    ":wat::holon::Reckoner/new-discrete",
                    item.clone(),
                )?;
                out.push((*h).clone());
            }
            out
        }
        other => {
            return Err(RuntimeError { span: args[3].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: ":wat::holon::Reckoner/new-discrete".into(),
                expected: "Vec of HolonAST",
                got: Box::new(ValueSnapshot::of(&other))
            } }.into())
        }
    };
    let r = holon::Reckoner::new(
        &name,
        dims as usize,
        recalib as usize,
        holon::ReckConfig::Discrete(label_asts),
    );
    Ok(Value::Reckoner(Arc::new(
        crate::rust_deps::ThreadOwnedCell::new(r),
    )))
}

