/// `(:wat::kernel::spawn-thread body) -> :wat::kernel::Thread<I,O>` —
/// arc 114 slice 1. Body is a function whose signature is
///   `:Fn(:Receiver<I>, :Sender<O>) -> :wat::core::nil`
/// (read input, write output, return nil). The body's "return value"
/// is a marker for "completed without panic," not a value carrier.
/// Values flow only through channels — this is the Program contract.
///
/// Allocates two unbounded channels (input + output) plus the
/// existing one-shot SpawnOutcome channel ProgramHandle::InThread
/// already uses. Spawns a std::thread, runs the body inside
/// `catch_unwind`, packages the outcome onto the SpawnOutcome
/// channel — same shape `eval_kernel_spawn`/`spawn_with_world_into_result`
/// use, so `Thread/join-result` reuses the join semantics unchanged.
///
/// Returns Thread<I,O> as the parent-facing struct: input is the
/// `Sender<I>` outside end (parent writes), output is the
/// `Receiver<O>` outside end (parent reads), join carries the
/// SpawnOutcome receiver.
///
/// The first argument may be a function-keyword path (looked up in
/// `sym`) or any expression evaluating to a fn value. Mirrors
/// `eval_kernel_spawn`'s long-standing accept-by-keyword-or-value
/// pattern — keeps both shapes available without forcing the user
/// to wrap everything in a fn-ref.
fn eval_kernel_spawn_thread(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::spawn-thread";
    if args.len() != 1 {
        return Err(RuntimeError { span: list_span.clone(), kind: RuntimeErrorKind::ArityMismatch {
            op: OP.into(),
            expected: 1,
            got: args.len()
        } }.into());
    }
    let body_fn = match &args[0] {
        WatAST::Keyword(k, kspan) => match sym.get(k) {
            Some(f) => f.clone(),
            None => return Err(RuntimeError { span: kspan.clone(), kind: RuntimeErrorKind::UnknownFunction(k.clone()) }.into()),
        },
        _ => match eval_inner(&args[0], env, sym)?.value_owned() {
            Value::wat__core__fn(f) => f,
            other => {
                return Err(RuntimeError { span: args[0].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                    op: OP.into(),
                    expected: "function keyword path or fn value",
                    got: Box::new(ValueSnapshot::of(&other))
                } }.into());
            }
        },
    };
    // Two unbounded channels: parent writes to input, thread reads;
    // thread writes to output, parent reads. Inside ends go to the
    // body; outside ends become Thread<I,O>'s input/output fields.
    let (in_tx, in_rx) = crossbeam_channel::unbounded::<Value>();
    let (out_tx, out_rx) = crossbeam_channel::unbounded::<Value>();
    // SpawnOutcome channel — same one-shot shape ProgramHandle expects.
    let (outcome_tx, outcome_rx) = crate::typed_channel::bounded::<SpawnOutcome>(1);
    let thread_sym = sym.clone();
    let span = crate::rust_caller_span!();
    // Derive the most informative name: prefer the keyword path from
    // args[0] (the WAT identifier the caller passed to spawn-thread),
    // fall back to the function's declared name, then to a generic marker.
    let thread_fn_name: String = match &args[0] {
        WatAST::Keyword(k, _) => k.clone(),
        _ => body_fn
            .name
            .as_deref()
            .unwrap_or(":wat::kernel::spawn-thread::<anon>")
            .to_string(),
    };
    let body_args = vec![
        crate::typed_channel::receiver_from_crossbeam(in_rx),
        crate::typed_channel::sender_from_crossbeam(out_tx),
    ];
    // Arc 170 slice 1f-γ — register the new thread with the three
    // stdio services so the body's `(:wat::kernel::println ...)` /
    // `(eprintln ...)` / `(readln)` calls have a populated ThreadIO.
    //
    // Lazy-registration pattern: when the carrier is None (service-
    // template's own internal spawn-thread call during service
    // bootstrap, OR a pre-orchestrator init path) the registration
    // step is skipped. Service threads never call the three substrate
    // primitives — their ThreadIO stays None and the
    // `ServiceNotRunning` error path is unreachable in practice.
    //
    // Registration is performed in the PARENT thread so any Add-send
    // failure (service shut down between carrier-set and spawn-thread)
    // surfaces synchronously to the parent rather than being lost
    // inside the spawned thread's closure. The resulting ThreadIO is
    // moved into the closure for installation in the new thread's
    // thread-local cell on entry.
    let registration: Option<(crate::thread_io::ThreadId, crate::thread_io::ThreadIO)> =
        match sym.runtime_services() {
            Some(services) => {
                let tid = crate::thread_io::next_thread_id();
                let io = crate::thread_io::register_thread_with_services(tid, services)?;
                Some((tid, io))
            }
            None => None,
        };
    // The carrier needed for the epilogue's deregister step is the
    // SAME Arc the parent reads — captured by value here so the
    // closure owns its own ref. Cheap (Arc clone).
    let registration_services: Option<Arc<crate::thread_io::RuntimeServices>> =
        sym.runtime_services().cloned();
    std::thread::Builder::new()
        .name(format!("wat-thread::{}", thread_fn_name))
        .spawn(move || {
            // BRIEF Q3 — install ThreadIO + register epilogue BEFORE
            // running the body. The epilogue runs after the body
            // returns or panics (inside the catch_unwind boundary the
            // body uses).
            let registration_thread_id =
                registration.as_ref().map(|(tid, _)| *tid);
            if let Some((_, io)) = registration {
                crate::thread_io::install_thread_io(io);
            }
            // Mirror eval_kernel_spawn's catch_unwind: panics in the
            // body surface as data on the outcome channel rather than
            // unwinding the thread silently. AssertUnwindSafe is honest;
            // body_args + thread_sym are owned by this closure, not
            // shared with the caller post-panic.
            let outcome = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                apply_function(body_fn, body_args, &thread_sym, span)
            })) {
                Ok(Ok(v)) => SpawnOutcome::Ok(v),
                Ok(Err(e)) => SpawnOutcome::RuntimeErr(e),
                Err(payload) => {
                    let (message, assertion) = extract_panic_payload(payload);
                    SpawnOutcome::Panic { message, assertion }
                }
            };
            // Epilogue: send Remove on the three ControlTxs (silent-
            // fail if services already down), uninstall this thread's
            // ThreadIO. ThreadIO drop closes its Rust-side Senders,
            // collapsing each bridge thread's `rust_rx`; bridge exits
            // → wat-side data_tx drops → service routing-table entry
            // becomes invalid and the service prunes on its next
            // select wake-up.
            if let (Some(tid), Some(services)) =
                (registration_thread_id, registration_services.as_ref())
            {
                crate::thread_io::deregister_thread_from_services(tid, services);
            }
            let _ = crate::thread_io::uninstall_thread_io();
            let _ = outcome_tx.send(outcome);
        })
        .expect("Thread::Builder::spawn failed");
    Ok(Value::Struct(Arc::new(StructValue {
        type_name: ":wat::kernel::Thread".into(),
        fields: vec![
            crate::typed_channel::sender_from_crossbeam(in_tx),
            crate::typed_channel::receiver_from_crossbeam(out_rx),
            Value::wat__kernel__ProgramHandle(Arc::new(
                ProgramHandleInner::InThread(outcome_rx),
            )),
        ],
    })))
}

/// `(:wat::kernel::Thread/join-result thr) ->
/// :wat::core::Result<:(), :wat::core::Vector<wat::kernel::ThreadDiedError>>` — arc 114 slice 1.
/// The in-thread sibling of arc 112's `Process/join-result`.
///
/// Pulls the Thread's join-field ProgramHandle and recv's the
/// SpawnOutcome. A Thread<I,O> always carries an InThread variant by
/// construction (Forked is the Process-side variant); the Forked arm
/// would indicate a substrate-level corruption and is treated as a
/// hard type-mismatch error rather than synthesized data.
///
/// Arc 113's chain shape applies: `Vec<ThreadDiedError>`, head =
/// the immediate thread that died, tail = the upstream chain its
/// panic carried (recovered from `AssertionPayload.upstream_chain`).
#[restricted_to(":wat::kernel::Thread/join-result", ":wat::")]
fn eval_kernel_thread_join_result(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::Thread/join-result";
    if args.len() != 1 {
        return Err(RuntimeError { span: list_span.clone(), kind: RuntimeErrorKind::ArityMismatch {
            op: OP.into(),
            expected: 1,
            got: args.len()
        } }.into());
    }
    let thread_value = eval_inner(&args[0], env, sym)?.value_owned();
    let thread_struct = match thread_value {
        Value::Struct(s) if s.type_name == ":wat::kernel::Thread" => s,
        other => {
            return Err(RuntimeError { span: args[0].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "wat::kernel::Thread",
                got: Box::new(ValueSnapshot::of(&other))
            } }.into());
        }
    };
    // Thread struct field order: input, output, join.
    let handle = match thread_struct.fields.get(2) {
        Some(Value::wat__kernel__ProgramHandle(h)) => h.clone(),
        _ => {
            return Err(RuntimeError { span: args[0].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Thread.join (ProgramHandle)",
                got: Box::new(ValueSnapshot::unavailable("missing or wrong-type field")),
                // arc 138: no — struct field lookup; no per-field AST
            } }.into());
        }
    };
    let value = match handle.as_ref() {
        ProgramHandleInner::InThread(rx) => match rx.recv() {
            Ok(SpawnOutcome::Ok(_)) => Value::Result(Arc::new(Ok(Value::Unit))),
            Ok(SpawnOutcome::RuntimeErr(e)) => Value::Result(Arc::new(Err(single_died_chain(
                thread_died_error_runtime(e.to_string()),
            )))),
            Ok(SpawnOutcome::Panic { message, assertion }) => {
                // Arc 113 chain conj — head is THIS thread's death,
                // tail is whatever panic-payload upstream chain rode in.
                let upstream = assertion.as_ref().and_then(|a| a.upstream_chain.clone());
                let fresh = thread_died_error_panic(message, assertion.clone());
                Value::Result(Arc::new(Err(conj_died_chain(fresh, upstream))))
            }
            Err(_) => Value::Result(Arc::new(Err(single_died_chain(
                thread_died_error_channel_disconnected(),
            )))),
        },
        ProgramHandleInner::Forked(_) => {
            return Err(RuntimeError { span: args[0].span().clone(), kind: RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Thread.join (InThread variant)",
                got: Box::new(ValueSnapshot::unavailable("Forked variant on a Thread<I,O> — substrate bug")),
                // arc 138: no — internal substrate invariant; no AST source
            } }.into());
        }
    };
    Ok(value)
}

