    fn math_exp_accepts_i64_promotion() {
        // :wat::std::math:: permits i64 → f64 promotion (matches
        // ln/log/sin/cos siblings); :wat::core::f64 namespace does not.
        assert_eq!(expect_f64(eval_expr("(:wat::std::math::exp 0)").unwrap()), 1.0);
    }

