        let result = run(
            r#"
            (:wat::core::defn :my::app::fact [n <- :wat::core::i64] -> :wat::core::i64
              (:wat::core::if (:wat::core::= n 0) -> :wat::core::i64
                                1
                                (:wat::core::i64::* n (:my::app::fact (:wat::core::i64::- n 1)))))
            (:my::app::fact 5)
            "#,
        )
        .unwrap();
        assert!(matches!(result, Value::i64(120)));
