    fn let_destructures_a_pair() {
        let src = r#"
            (:wat::core::let [[a b] p] (:wat::core::i64::+ a b))
        "#;
        let p = pair(Value::i64(3), Value::i64(4));
        match eval_with_binding(src, "p", p).unwrap() {
            Value::i64(7) => {}
            v => panic!("expected 7, got {:?}", v),
        }
    }

